const rows = $input.all().map((item) => item.json);
const commerce = new Set(['shopify', 'amazon', 'backerkit', 'kickstarter', 'retail', 'wholesale', 'direct']);
const paid = new Set(['meta', 'meta_ads', 'facebook', 'instagram', 'google', 'google_ads', 'tiktok', 'pinterest', 'bing', 'microsoft_ads']);
const aliases = {
  meta: { key: 'meta_ads', label: 'Meta Ads' },
  facebook: { key: 'meta_ads', label: 'Meta Ads' },
  instagram: { key: 'meta_ads', label: 'Meta Ads' },
  google: { key: 'google_ads', label: 'Google Ads' },
  google_ads: { key: 'google_ads', label: 'Google Ads' },
  microsoft_ads: { key: 'microsoft_ads', label: 'Microsoft Ads' },
};
const normalize = (value) => String(value ?? 'unknown').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'unknown';
const toDate = (value) => String(value).slice(0, 10);
const groupedRows = new Map();
for (const row of rows) {
  const normalized = normalize(row.channel);
  const alias = aliases[normalized] ?? {
    key: normalized,
    label: normalized.split('_').map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' '),
  };
  const group = groupedRows.get(alias.key) ?? {
    key: alias.key,
    label: alias.label,
    normalized,
    rows: [],
  };
  group.rows.push(row);
  groupedRows.set(alias.key, group);
}
const output = [];
const chunkSize = 3500;
const finishedAt = new Date().toISOString();
for (const group of groupedRows.values()) {
  const hasSpend = group.rows.some((row) => Number(row.spend ?? 0) !== 0);
  const type = paid.has(group.normalized) || hasSpend
    ? 'paid_media'
    : commerce.has(group.normalized)
      ? 'commerce'
      : 'custom';
  const metrics = [];
  let minDate = null;
  let maxDate = null;
  for (const row of group.rows) {
    const date = toDate(row.date);
    minDate = !minDate || date < minDate ? date : minDate;
    maxDate = !maxDate || date > maxDate ? date : maxDate;
    const sourceUpdatedAt = row.updated_at ?? null;
    if (type === 'paid_media') {
      metrics.push({ date, metric: 'ad_spend', value: Number(row.spend ?? 0), unit: 'USD', sourceUpdatedAt });
      metrics.push({ date, metric: 'attributed_revenue', value: Number(row.revenue ?? 0), unit: 'USD', sourceUpdatedAt });
      metrics.push({ date, metric: 'conversions', value: Number(row.conversions ?? 0), unit: 'count', sourceUpdatedAt });
    } else {
      metrics.push({ date, metric: 'sales_revenue', value: Number(row.revenue ?? 0), unit: 'USD', sourceUpdatedAt });
      metrics.push({ date, metric: 'orders', value: Number(row.orders ?? 0), unit: 'count', sourceUpdatedAt });
    }
  }
  for (let start = 0; start < metrics.length; start += chunkSize) {
    const batch = metrics.slice(start, start + chunkSize);
    const batchNumber = Math.floor(start / chunkSize) + 1;
    output.push({ json: {
      source: { key: group.key, type, displayName: group.label },
      run: {
        key: `${group.key}-backfill-${minDate}-${maxDate}-batch-${batchNumber}`,
        status: 'success',
        startedAt: finishedAt,
        finishedAt,
        rowsRead: batch.length,
        rowsWritten: batch.length,
        rowsFailed: 0,
      },
      metrics: batch,
      products: [],
      inventory: [],
      records: [],
    }});
  }
}
return output;

const rows = $input.all().map((item) => item.json);
const chunkSize = 1000;
const output = [];
const finishedAt = new Date().toISOString();
for (let start = 0; start < rows.length; start += chunkSize) {
  const batchRows = rows.slice(start, start + chunkSize);
  const products = batchRows.map((row) => ({
    date: String(row.date).slice(0, 10),
    productKey: String(row.product_id),
    productName: String(row.product_name ?? row.product_id),
    unitsSold: Number(row.units_sold ?? 0),
    grossRevenue: 0,
    netRevenue: 0,
    refunds: 0,
    currency: 'USD',
    sourceUpdatedAt: row.updated_at ?? null
  }));
  const dates = products.map((row) => row.date).sort();
  output.push({ json: {
    source: { key: 'shopify', type: 'commerce', displayName: 'Shopify' },
    run: {
      key: `shopify-products-backfill-${dates[0] ?? 'empty'}-${dates.at(-1) ?? 'empty'}-batch-${Math.floor(start / chunkSize) + 1}`,
      status: 'success',
      startedAt: finishedAt,
      finishedAt,
      rowsRead: products.length,
      rowsWritten: products.length,
      rowsFailed: 0
    },
    metrics: [],
    products,
    inventory: [],
    records: []
  }});
}
return output;

const rows = $input.all().map((item) => item.json);
const chunkSize = 1000;
const output = [];
const finishedAt = new Date().toISOString();
for (let start = 0; start < rows.length; start += chunkSize) {
  const inventory = rows.slice(start, start + chunkSize).map((row) => ({
    productKey: String(row.product_id),
    productName: String(row.product_name ?? row.product_id),
    capturedAt: row.snapshot_at ?? finishedAt,
    available: row.available_quantity === null || row.available_quantity === undefined ? null : Number(row.available_quantity)
  }));
  output.push({ json: {
    source: { key: 'shopify', type: 'commerce', displayName: 'Shopify' },
    run: {
      key: `shopify-inventory-backfill-${finishedAt.slice(0, 13)}-batch-${Math.floor(start / chunkSize) + 1}`,
      status: 'success',
      startedAt: finishedAt,
      finishedAt,
      rowsRead: inventory.length,
      rowsWritten: inventory.length,
      rowsFailed: 0
    },
    metrics: [],
    products: [],
    inventory,
    records: []
  }});
}
return output;
